// ─── TEMPS, LUNE, MARÉE ───
const EPOCH = Date.UTC(2000,0,6,18,14);                 // nouvelle lune de référence
const SYNODIC_H = 29.530588*24, TIDE_H = 12.4206;        // heures
const tH = (ms) => (ms - EPOCH)/3.6e6;                   // heures depuis l'époque
const moonPhase = (t) => ((t/SYNODIC_H)%1+1)%1;         // 0 nouvelle, 0.5 pleine
const tideAmp = (t) => 1.05 + 0.25*Math.cos(2*Math.PI*t/(SYNODIC_H/2)); // 0.80 morte-eau .. 1.30 vive-eau
const tide = (t) => tideAmp(t)*Math.sin(2*Math.PI*t/TIDE_H);           // hauteur ; seuil SILL = 0.72
const SILL = 0.72;
const localHour = (ms) => { const d = new Date(ms); return d.getHours() + d.getMinutes()/60; };
const isNight = (h) => h < 6.5 || h >= 21.5;
const seasonEndMs = (startMs) => startMs + SYNODIC_H*3.6e6;   // la lune revient à sa phase du premier jour
const clamp = (x,a,b) => Math.max(a, Math.min(b, x));
// ─── MÉTÉO PARTAGÉE (phases = hash de la date de début de saison, identiques pour tous) ───
const phases = (seed) => { let s = seed*9301+49297; const o=[]; for (let i=0;i<4;i++){ s=(s*9301+49297)%233280; o.push(2*Math.PI*s/233280);} return o; };
const pressure = (t, ph) => 1013 + 6*Math.sin(2*Math.PI*t/55.2+ph[0]) + 5*Math.sin(2*Math.PI*t/98.4+ph[1]) + 4*Math.sin(2*Math.PI*t/190+ph[2]) + 3*Math.sin(2*Math.PI*t/329+ph[3]);
const rainMmH = (P, dP) => (P < 1005 && dP < 0) ? Math.min(4, (1005-P)*0.6) : 0;   // dP = pression(t+1h) - pression(t)
const wind01 = (P, dP) => clamp(0.1 + 0.9*Math.abs(dP) + Math.max(0, 1010-P)/20, 0, 1);
const Tmid = (day) => 20 + 7*Math.sin(Math.PI*Math.min(day,30)/36);               // 20 (juin) -> 27 (jour 18) -> 23.5
const tempC = (day, hour, P, rain) => Tmid(day) + 6*Math.cos(2*Math.PI*(hour-16)/24) - (P<1008?4:0) - (rain>0?2:0);
// garantie 72 h : if (t - tutorialEnd < 72) P = Math.max(P, 1012); et averse scriptée jour 3, 14h-16h : P = 1002, dP = -0.3
// ─── PARCELLES ───
const TYPES = { vasiere:{floor:0,max:40,area:8}, cobier:{floor:-5,max:20,area:4}, fare:{floor:-10,max:10,area:3}, aderne:{floor:-15,max:5,area:2}, oeillet:{floor:-20,max:2,area:1} };
const L_PER_CM = 700;                                        // litres par cm pour 1 unité (70 m²)
const cap = (c) => TYPES[c.type].area*L_PER_CM;              // L par cm
const maxDepth = (c, st) => c.type==='vasiere' ? 40*Math.pow(1.5, st.vasEnl) : (c.type==='oeillet' && st.enEau ? 8 : TYPES[c.type].max);
const salinity = (c) => c.depth > 0 ? c.salt/(c.depth*cap(c)) : 0;   // g/L ; c.salt en grammes
const canFeed = (pt, ct) => { const d = TYPES[pt].floor - TYPES[ct].floor; return (d>0 && d<=10) || (d===0 && ct==='oeillet'); }; // une trappe existe si vrai
const bucket = (S) => S<=0 ? 'sec' : S<80 ? 'canard' : S<150 ? 'violet30' : S<220 ? 'violet60' : S<258 ? 'rose' : 'blanc';
