//    fleur (œillet) : if (depth>0 && S>=250 && T>22 && w<0.4 && rain===0 && hour>=15 && hour<20) fleur = min(1.5, fleur + 0.25*dt)
// ─── AFFICHAGE, ÉCONOMIE ───
const YIELD_DIV = 14;                                        // grammes simulés -> kg affichés
const kgDisplay = (g) => g/1000/YIELD_DIV;                   // œillet saturé nourri à 250 g/L ≈ 60-80 kg/jour
const saltDots = (kg) => Math.floor(kg/4);                   // points blancs dessinés
const PRICE = { gros: 0.80, fleur: 12 };                     // EUR/kg, fixes pour la saison
const COST = { oeillet:60, aderne:110, fare:150, cobier:180, vasiere:300, clapet:25, barometre:80, lousse:120, rhabillage:60 };
const plotCost = (type, nOwned) => type==='vasiere' ? 300*Math.pow(1.5, nOwned) : COST[type]*(1 + 0.10*nOwned);
const storageDays = (cells, st) => cells.reduce((a,c)=>a+maxDepth(c,st)*TYPES[c.type].area,0) / cells.reduce((a,c)=>a+3.5*TYPES[c.type].area,0); // le carnet écrit « réserve : N jours »
const yieldEurDay = (Aup, N) => (3.5*700*0.80/(YIELD_DIV*1000)) * Math.min((Aup+N)*35, N*258); // Aup = surface amont en unités, N = œillets ; régime permanent, pour la projection du carnet
const recordKgParOeilletJour = (kgSaison, sommeJournaliereDesOeillets) => kgSaison / sommeJournaliereDesOeillets;
const rowsForSeason = (seasonsDone) => Math.min(11, 5 + 2*seasonsDone);
